// RTL Languages list (Urdu, Kashmiri, Sindhi in Perso-Arabic scripts)
const RTL_LANGUAGES = ['ur', 'ks', 'sd'];

function isRTL(lang) {
  return RTL_LANGUAGES.includes(lang);
}

// Active language resolution
let currentLang = localStorage.getItem('agri_lang') || 'en';
// Normalize legacy 'maithili' to 'mai'
if (currentLang === 'maithili') {
  currentLang = 'mai';
  localStorage.setItem('agri_lang', 'mai');
}
if (!translations[currentLang]) {
  currentLang = 'en';
}

/**
 * Get translated text for a key with parameter interpolation
 */
function t(key, params = {}) {
  const langObj = translations[currentLang] || translations.en;
  let text = langObj[key] || translations.en[key] || key;

  // Replace parameters like {amount}
  for (const [pKey, pVal] of Object.entries(params)) {
    text = text.replace(new RegExp(`\\{${pKey}\\}`, 'g'), pVal);
  }
  return text;
}

/**
 * Helper to get localized product name based on active language
 */
function getProductName(productOrId, defaultName = '') {
  const id = typeof productOrId === 'object' && productOrId ? (productOrId.id || productOrId.productId) : productOrId;
  const name = typeof productOrId === 'object' && productOrId ? productOrId.name : defaultName;
  if (id && translations[currentLang] && translations[currentLang][`prod_name_${id}`]) {
    return translations[currentLang][`prod_name_${id}`];
  }
  return name || id || '';
}

/**
 * Populate all 23 languages in the dropdown selector
 */
function populateLanguageDropdown() {
  const langSelects = document.querySelectorAll('#globalLanguageSelect, select.lang-select');
  langSelects.forEach(select => {
    if (!select) return;
    
    // Populate only if not already populated with all 23 languages
    if (select.options.length !== SUPPORTED_LANGUAGES.length) {
      select.innerHTML = SUPPORTED_LANGUAGES.map(lang => 
        `<option value="${lang.code}">${lang.label}</option>`
      ).join('');
    }
    
    select.value = currentLang;

    // Attach change listener if not already attached
    if (!select.dataset.listenerAttached) {
      select.dataset.listenerAttached = 'true';
      select.addEventListener('change', (e) => {
        setLanguage(e.target.value);
      });
    }
  });
}

/**
 * Update all DOM elements with data-i18n attributes
 */
function updatePageLanguage() {
  // Update text content
  document.querySelectorAll('[data-i18n]').forEach(el => {
    const key = el.getAttribute('data-i18n');
    if (key) {
      el.textContent = t(key);
    }
  });

  // Update HTML content if specified
  document.querySelectorAll('[data-i18n-html]').forEach(el => {
    const key = el.getAttribute('data-i18n-html');
    if (key) {
      el.innerHTML = t(key);
    }
  });

  // Update placeholders
  document.querySelectorAll('[data-i18n-placeholder]').forEach(el => {
    const key = el.getAttribute('data-i18n-placeholder');
    if (key) {
      el.setAttribute('placeholder', t(key));
    }
  });

  // Update titles
  document.querySelectorAll('[data-i18n-title]').forEach(el => {
    const key = el.getAttribute('data-i18n-title');
    if (key) {
      el.setAttribute('title', t(key));
    }
  });

  // Keep dropdown values in sync
  document.querySelectorAll('#globalLanguageSelect, select.lang-select').forEach(select => {
    if (select && select.value !== currentLang) {
      select.value = currentLang;
    }
  });
}

/**
 * Set current language, update RTL/LTR direction, and immediately refresh DOM
 */
function setLanguage(lang) {
  if (translations[lang] || SUPPORTED_LANGUAGES.some(l => l.code === lang)) {
    currentLang = lang;
    localStorage.setItem('agri_lang', lang);
    document.documentElement.lang = lang;
    document.documentElement.dir = isRTL(lang) ? 'rtl' : 'ltr';
    updatePageLanguage();
    
    // Dispatch custom event so pages can re-render dynamic elements
    window.dispatchEvent(new CustomEvent('languageChanged', { detail: { lang } }));
  }
}

// Initialize on DOM load and immediately
function initI18n() {
  document.documentElement.lang = currentLang;
  document.documentElement.dir = isRTL(currentLang) ? 'rtl' : 'ltr';
  populateLanguageDropdown();
  updatePageLanguage();
}

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', initI18n);
} else {
  initI18n();
}
